-- ksei.vw_f_ksei_monthly_delta_v2
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_f_ksei_monthly_delta_v2 AS WITH raw AS (SELECT ms.Code AS stock_code, ms.Date AS snapshot_date, ms.Price AS price_idr, ms."Sec._Num" AS listed_shares, ms.Total_Shares, ms.Total_Local, ms.Total_Foreign, ms.Is_Split_Suspect, ms.Is_Reverse_Suspect, (ms.Total_Shares * ms.Price) AS mktcap_proxy, ((((ms.Local_CP_Chg_Val + ms.Local_PF_Chg_Val) + ms.Local_IB_Chg_Val) + ms.Local_IS_Chg_Val) + ms.Local_MF_Chg_Val) AS local_sm_val, ((((((((ms.Foreign_IS_Chg_Val + ms.Foreign_CP_Chg_Val) + ms.Foreign_PF_Chg_Val) + ms.Foreign_IB_Chg_Val) + ms.Foreign_ID_Chg_Val) + ms.Foreign_MF_Chg_Val) + ms.Foreign_SC_Chg_Val) + ms.Foreign_FD_Chg_Val) + ms.Foreign_OT_Chg_Val) AS foreign_sm_val, ms.Local_ID_Chg_Val, ms.Top_Buyer, ms.Top_Buyer_Val, ms.Top_Seller, ms.Top_Seller_Val FROM ksei.monthly_snapshot AS ms), with_flags AS (SELECT *, (local_sm_val + foreign_sm_val) AS smart_money_chg_val, CASE  WHEN ((mktcap_proxy <= 0)) THEN (CAST('f' AS BOOLEAN)) WHEN (((mktcap_proxy > 5000000000000.0) AND (abs((local_sm_val + foreign_sm_val)) > (mktcap_proxy * 0.15)))) THEN (CAST('t' AS BOOLEAN)) WHEN (((mktcap_proxy > 5000000000000.0) AND (abs((local_sm_val + foreign_sm_val)) > 1500000000000.0) AND (abs((local_sm_val + foreign_sm_val)) > (mktcap_proxy * 0.07)))) THEN (CAST('t' AS BOOLEAN)) WHEN (((mktcap_proxy BETWEEN 1000000000000.0 AND 5000000000000.0) AND (abs((local_sm_val + foreign_sm_val)) > (mktcap_proxy * 0.12)))) THEN (CAST('t' AS BOOLEAN)) WHEN (((mktcap_proxy < 1000000000000.0) AND (abs((local_sm_val + foreign_sm_val)) > (mktcap_proxy * 0.07)) AND (abs((local_sm_val + foreign_sm_val)) > 5000000000.0))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS Is_CorpAction_Suspect FROM raw)SELECT stock_code, snapshot_date, price_idr, Total_Shares, Total_Local, Total_Foreign, Is_Split_Suspect, Is_Reverse_Suspect, Is_CorpAction_Suspect, round(((CAST(Total_Local AS DOUBLE) / "nullif"(Total_Shares, 0)) * 100), 4) AS local_pct, round(((CAST(Total_Foreign AS DOUBLE) / "nullif"(Total_Shares, 0)) * 100), 4) AS foreign_pct, local_sm_val, foreign_sm_val, smart_money_chg_val, Local_ID_Chg_Val AS retail_chg_val, CASE  WHEN (Is_CorpAction_Suspect) THEN (NULL) ELSE round((local_sm_val / 1000000000.0), 3) END AS local_smart_miliar, CASE  WHEN (Is_CorpAction_Suspect) THEN (NULL) ELSE round((foreign_sm_val / 1000000000.0), 3) END AS foreign_smart_miliar, CASE  WHEN (Is_CorpAction_Suspect) THEN (NULL) ELSE round((smart_money_chg_val / 1000000000.0), 3) END AS smart_money_miliar, round((Local_ID_Chg_Val / 1000000000.0), 3) AS retail_miliar, Top_Buyer, Top_Buyer_Val, Top_Seller, Top_Seller_Val FROM with_flags;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_f_ksei_rolling_trend
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_f_ksei_rolling_trend AS SELECT stock_code, snapshot_date, price_idr, smart_money_miliar, local_smart_miliar, foreign_smart_miliar, retail_miliar, round(sum(smart_money_miliar) OVER (PARTITION BY stock_code ORDER BY snapshot_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 3) AS sm_3m_cumulative_miliar, round(sum(smart_money_miliar) OVER (PARTITION BY stock_code ORDER BY snapshot_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW), 3) AS sm_6m_cumulative_miliar, local_pct, foreign_pct, sum(CASE  WHEN ((smart_money_miliar > 0)) THEN (1) ELSE 0 END) OVER (PARTITION BY stock_code ORDER BY snapshot_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS sm_positive_months_6m, round((smart_money_miliar - lag(smart_money_miliar) OVER (PARTITION BY stock_code ORDER BY snapshot_date)), 3) AS sm_mom_delta, (smart_money_miliar > 0) AS sm_positive, ((smart_money_miliar > 0) AND (lag(smart_money_miliar, 1) OVER (PARTITION BY stock_code ORDER BY snapshot_date) > 0)) AS sm_2m_positive, ((smart_money_miliar > 0) AND (lag(smart_money_miliar, 1) OVER (PARTITION BY stock_code ORDER BY snapshot_date) > 0) AND (lag(smart_money_miliar, 2) OVER (PARTITION BY stock_code ORDER BY snapshot_date) > 0)) AS sm_3m_positive, CASE  WHEN (((smart_money_miliar > 0) AND (retail_miliar < 0))) THEN ('DIVERGENT_BULLISH') WHEN (((smart_money_miliar < 0) AND (retail_miliar > 0))) THEN ('DIVERGENT_BEARISH') WHEN (((smart_money_miliar > 0) AND (retail_miliar > 0))) THEN ('ALIGNED_BULLISH') WHEN (((smart_money_miliar < 0) AND (retail_miliar < 0))) THEN ('ALIGNED_BEARISH') ELSE 'MIXED' END AS smart_retail_divergence, CASE  WHEN (((smart_money_miliar > 0) AND (lag(smart_money_miliar, 1) OVER (PARTITION BY stock_code ORDER BY snapshot_date) > 0) AND (lag(smart_money_miliar, 2) OVER (PARTITION BY stock_code ORDER BY snapshot_date) > 0))) THEN ('CONSISTENT_ACCUMULATION') WHEN (((smart_money_miliar > 0) AND (COALESCE(lag(smart_money_miliar, 1) OVER (PARTITION BY stock_code ORDER BY snapshot_date), 0) <= 0))) THEN ('NEW_ACCUMULATION') WHEN (((smart_money_miliar < 0) AND (lag(smart_money_miliar, 1) OVER (PARTITION BY stock_code ORDER BY snapshot_date) < 0) AND (lag(smart_money_miliar, 2) OVER (PARTITION BY stock_code ORDER BY snapshot_date) < 0))) THEN ('CONSISTENT_DISTRIBUTION') WHEN (((smart_money_miliar < 0) AND (COALESCE(lag(smart_money_miliar, 1) OVER (PARTITION BY stock_code ORDER BY snapshot_date), 0) >= 0))) THEN ('NEW_DISTRIBUTION') ELSE 'NEUTRAL' END AS sm_trend, Is_Split_Suspect, Is_Reverse_Suspect, sector, group_name FROM ksei.vw_f_ksei_monthly_delta;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_group_ksei_smart_money
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_group_ksei_smart_money AS WITH monthly_3m AS (SELECT ms.Code, ms.Date, ((ms.Local_CP_Chg_Val + ms.Local_PF_Chg_Val) + ms.Local_IB_Chg_Val) AS local_smart_val, ((ms.Foreign_CP_Chg_Val + ms.Foreign_PF_Chg_Val) + ms.Foreign_IB_Chg_Val) AS foreign_smart_val, ms.Local_ID_Chg_Val AS local_retail_val, ms.Local_CP_Chg_Val, ms.Local_PF_Chg_Val, ms.Local_IB_Chg_Val, ms.Foreign_CP_Chg_Val, ms.Foreign_PF_Chg_Val, ms.Foreign_IB_Chg_Val, ms.Top_Buyer, ms.Top_Buyer_Val, ms.Top_Seller, ms.Top_Seller_Val, cp.group_name FROM ksei.monthly_snapshot AS ms INNER JOIN market.company_profile AS cp ON ((ms.Code = cp.stock_code)) WHERE ((cp.group_name != 'Others') AND (ms.Date >= ((SELECT max(Date) FROM ksei.monthly_snapshot) - CAST('90 days' AS INTERVAL))))), group_monthly AS (SELECT group_name, Date, count(DISTINCT Code) AS stock_count, round((sum(local_smart_val) / 1000000000.0), 2) AS local_smart_miliar, round((sum(foreign_smart_val) / 1000000000.0), 2) AS foreign_smart_miliar, round((sum((local_smart_val + foreign_smart_val)) / 1000000000.0), 2) AS total_smart_miliar, round((sum(local_retail_val) / 1000000000.0), 2) AS local_retail_miliar, round((sum(Local_CP_Chg_Val) / 1000000000.0), 2) AS local_cp_miliar, round((sum(Local_PF_Chg_Val) / 1000000000.0), 2) AS local_pf_miliar, round((sum(Local_IB_Chg_Val) / 1000000000.0), 2) AS local_ib_miliar, round((sum(Foreign_CP_Chg_Val) / 1000000000.0), 2) AS foreign_cp_miliar, round((sum(Foreign_PF_Chg_Val) / 1000000000.0), 2) AS foreign_pf_miliar, round((sum(Foreign_IB_Chg_Val) / 1000000000.0), 2) AS foreign_ib_miliar, "mode"() WITHIN GROUP ( ORDER BY Top_Buyer) AS group_top_buyer, "mode"() WITHIN GROUP ( ORDER BY Top_Seller) AS group_top_seller, round((sum(Top_Buyer_Val) / 1000000000.0), 2) AS group_top_buyer_val_miliar, round((sum(Top_Seller_Val) / 1000000000.0), 2) AS group_top_seller_val_miliar FROM monthly_3m GROUP BY group_name, Date), with_lag AS (SELECT *, lag(total_smart_miliar) OVER (PARTITION BY group_name ORDER BY Date) AS prev_m1_smart, lag(total_smart_miliar, 2) OVER (PARTITION BY group_name ORDER BY Date) AS prev_m2_smart, row_number() OVER (PARTITION BY group_name ORDER BY Date DESC) AS rn FROM group_monthly), latest AS (SELECT *, CASE  WHEN (((total_smart_miliar > 0) AND (COALESCE(prev_m1_smart, 0) > 0) AND (COALESCE(prev_m2_smart, 0) > 0))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS konsisten_3_bulan FROM with_lag WHERE (rn = 1))SELECT l.group_name, l.Date AS latest_month, l.stock_count, l.local_smart_miliar, l.foreign_smart_miliar, l.total_smart_miliar, l.local_retail_miliar, l.local_cp_miliar, l.local_pf_miliar, l.local_ib_miliar, l.foreign_cp_miliar, l.foreign_pf_miliar, l.foreign_ib_miliar, l.group_top_buyer, l.group_top_seller, l.group_top_buyer_val_miliar, l.prev_m1_smart AS m1_smart_miliar, l.prev_m2_smart AS m2_smart_miliar, round((l.total_smart_miliar - COALESCE(l.prev_m1_smart, 0)), 2) AS smart_mom_delta, l.konsisten_3_bulan, CASE  WHEN (((l.total_smart_miliar > 0) AND (COALESCE(l.prev_m1_smart, 0) > 0))) THEN ('KONSISTEN_AKUMULASI') WHEN (((l.total_smart_miliar > 0) AND (COALESCE(l.prev_m1_smart, 0) <= 0))) THEN ('MULAI_AKUMULASI') WHEN (((l.total_smart_miliar < 0) AND (COALESCE(l.prev_m1_smart, 0) < 0))) THEN ('KONSISTEN_DISTRIBUSI') WHEN (((l.total_smart_miliar < 0) AND (COALESCE(l.prev_m1_smart, 0) >= 0))) THEN ('MULAI_DISTRIBUSI') ELSE 'NEUTRAL' END AS smart_money_trend, CASE  WHEN (((l.total_smart_miliar > 0) AND (l.local_retail_miliar < 0))) THEN ('DIVERGEN_BULLISH') WHEN (((l.total_smart_miliar < 0) AND (l.local_retail_miliar > 0))) THEN ('DIVERGEN_BEARISH') WHEN (((l.total_smart_miliar > 0) AND (l.local_retail_miliar > 0))) THEN ('SEMUA_BULLISH') WHEN (((l.total_smart_miliar < 0) AND (l.local_retail_miliar < 0))) THEN ('SEMUA_BEARISH') ELSE 'MIXED' END AS divergence_signal, CASE  WHEN (((l.local_smart_miliar > 0) AND (l.foreign_smart_miliar > 0))) THEN ('KOMPAK_BELI') WHEN (((l.local_smart_miliar < 0) AND (l.foreign_smart_miliar < 0))) THEN ('KOMPAK_JUAL') WHEN (((l.local_smart_miliar > 0) AND (l.foreign_smart_miliar < 0))) THEN ('LOKAL_BELI_ASING_JUAL') WHEN (((l.local_smart_miliar < 0) AND (l.foreign_smart_miliar > 0))) THEN ('ASING_BELI_LOKAL_JUAL') ELSE 'MIXED' END AS institution_alignment, CAST(least(100, greatest(0, ((((CASE  WHEN ((l.total_smart_miliar > 1000)) THEN (35) WHEN ((l.total_smart_miliar > 500)) THEN (25) WHEN ((l.total_smart_miliar > 100)) THEN (15) WHEN ((l.total_smart_miliar > 0)) THEN (8) ELSE 0 END + CASE  WHEN (((l.local_smart_miliar > 0) AND (l.foreign_smart_miliar > 0))) THEN (25) WHEN (((l.local_smart_miliar > 0) OR (l.foreign_smart_miliar > 0))) THEN (12) ELSE 0 END) + CASE  WHEN ((l.total_smart_miliar > (COALESCE(l.prev_m1_smart, 0) + 100))) THEN (20) WHEN ((l.total_smart_miliar > COALESCE(l.prev_m1_smart, 0))) THEN (10) ELSE 0 END) + CASE  WHEN (((l.local_retail_miliar < -200) AND (l.total_smart_miliar > 0))) THEN (12) WHEN (((l.local_retail_miliar < 0) AND (l.total_smart_miliar > 0))) THEN (6) ELSE 0 END) + CASE  WHEN (l.konsisten_3_bulan) THEN (8) ELSE 0 END))) AS INTEGER) AS ksei_conviction_score FROM latest AS l ORDER BY ksei_conviction_score DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_group_ownership
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_group_ownership AS WITH latest_ksei AS (SELECT max(date) AS max_date FROM ksei.ownership_1pct), latest_daily AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), group_ksei AS (SELECT cp.group_name, count(DISTINCT o.share_code) AS total_stocks, round(avg(o.percentage), 2) AS avg_ownership_pct, sum(o.total_holding_shares) AS total_shares, count(DISTINCT o.investor_name) AS total_investors, sum(CASE  WHEN ((o.local_foreign IN ('F', 'A'))) THEN (o.percentage) ELSE 0 END) AS foreign_ownership_pct, sum(CASE  WHEN ((o.local_foreign IN ('L', 'D', 'I'))) THEN (o.percentage) ELSE 0 END) AS local_ownership_pct FROM ksei.ownership_1pct AS o INNER JOIN market.company_profile AS cp ON ((o.share_code = cp.stock_code)) WHERE ((cp.group_name != 'Others') AND (o.date = (SELECT max_date FROM latest_ksei))) GROUP BY cp.group_name), group_flow AS (SELECT cp.group_name, sum(d.net_foreign_value) AS total_foreign_flow, sum(d."value") AS total_value, round(avg(d.change_percent), 2) AS avg_change_pct, count(CASE  WHEN ((d.change_percent > 0)) THEN (1) ELSE NULL END) AS gainers, count(CASE  WHEN ((d.change_percent < 0)) THEN (1) ELSE NULL END) AS losers FROM market.daily_transactions AS d INNER JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE ((cp.group_name != 'Others') AND (d.trading_date = (SELECT max_date FROM latest_daily))) GROUP BY cp.group_name)SELECT gk.group_name, gk.total_stocks, gk.avg_ownership_pct, gk.foreign_ownership_pct, gk.local_ownership_pct, gk.total_shares, gk.total_investors, COALESCE(gf.total_foreign_flow, 0) AS total_foreign_flow, COALESCE(gf.total_value, 0) AS total_value, COALESCE(gf.avg_change_pct, 0) AS avg_change_pct, COALESCE(gf.gainers, 0) AS gainers, COALESCE(gf.losers, 0) AS losers, CASE  WHEN ((COALESCE(gf.total_foreign_flow, 0) > 50000000000)) THEN ('🔥 MASSIVE INFLOW') WHEN ((COALESCE(gf.total_foreign_flow, 0) > 10000000000)) THEN ('📈 INFLOW') WHEN ((COALESCE(gf.total_foreign_flow, 0) < -50000000000)) THEN ('🔻 MASSIVE OUTFLOW') WHEN ((COALESCE(gf.total_foreign_flow, 0) < -10000000000)) THEN ('📉 OUTFLOW') ELSE '➖ NEUTRAL' END AS flow_signal FROM group_ksei AS gk LEFT JOIN group_flow AS gf ON ((gk.group_name = gf.group_name)) ORDER BY gk.total_stocks DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_insider_screener
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_insider_screener AS WITH latest_date AS (SELECT max(CAST(date AS "DATE")) AS curr_date FROM ksei.ownership_1pct), prev_date AS (SELECT max(CAST(date AS "DATE")) AS prev_date FROM ksei.ownership_1pct WHERE (CAST(date AS "DATE") < (SELECT curr_date FROM latest_date))), current_data AS (SELECT o.share_code, o.investor_name, o.investor_type, o.local_foreign, o.percentage AS curr_pct, o.total_holding_shares AS curr_shares FROM ksei.ownership_1pct AS o , latest_date AS l WHERE (CAST(o.date AS "DATE") = l.curr_date)), previous_data AS (SELECT o.share_code, o.investor_name, o.percentage AS prev_pct, o.total_holding_shares AS prev_shares FROM ksei.ownership_1pct AS o , prev_date AS p WHERE (CAST(o.date AS "DATE") = p.prev_date)), stock_aggregate AS (SELECT c.share_code, sum(CASE  WHEN ((c.investor_type IN ('CP', 'Corporate'))) THEN (c.curr_pct) ELSE 0 END) AS corp_curr, sum(CASE  WHEN ((c.local_foreign IN ('F', 'A'))) THEN (c.curr_pct) ELSE 0 END) AS foreign_curr, sum(CASE  WHEN ((c.investor_type IN ('ID', 'Individual'))) THEN (c.curr_pct) ELSE 0 END) AS ind_curr, sum(CASE  WHEN ((c.investor_type IN ('MF', 'Mutual Funds', 'Fund Manager'))) THEN (c.curr_pct) ELSE 0 END) AS fund_curr, sum(CASE  WHEN ((c.investor_type IN ('IB', 'Bank', 'Financial Institutional'))) THEN (c.curr_pct) ELSE 0 END) AS fin_curr, COALESCE(sum(CASE  WHEN (((p.investor_name IS NOT NULL) AND (c.investor_type IN ('CP', 'Corporate')))) THEN (p.prev_pct) ELSE 0 END), 0) AS corp_prev, COALESCE(sum(CASE  WHEN (((p.investor_name IS NOT NULL) AND (c.local_foreign IN ('F', 'A')))) THEN (p.prev_pct) ELSE 0 END), 0) AS foreign_prev, COALESCE(sum(CASE  WHEN (((p.investor_name IS NOT NULL) AND (c.investor_type IN ('ID', 'Individual')))) THEN (p.prev_pct) ELSE 0 END), 0) AS ind_prev FROM current_data AS c LEFT JOIN previous_data AS p ON (((c.share_code = p.share_code) AND (c.investor_name = p.investor_name))) GROUP BY c.share_code)SELECT sa.share_code AS code, (sa.corp_curr - sa.corp_prev) AS corp_change, (sa.foreign_curr - sa.foreign_prev) AS foreign_change, (sa.ind_curr - sa.ind_prev) AS ind_change, (((((CASE  WHEN ((((sa.corp_curr - sa.corp_prev) > 1) AND ((sa.ind_curr - sa.ind_prev) < -0.5))) THEN (3) ELSE 0 END + CASE  WHEN (((sa.foreign_curr - sa.foreign_prev) > 1)) THEN (2) ELSE 0 END) + CASE  WHEN ((((sa.corp_curr + sa.fund_curr) + sa.fin_curr) > 50)) THEN (1) ELSE 0 END) + CASE  WHEN ((((sa.corp_curr - sa.corp_prev) < -1) AND ((sa.ind_curr - sa.ind_prev) > 0.5))) THEN (-2) ELSE 0 END) + CASE  WHEN (((sa.foreign_curr - sa.foreign_prev) < -1)) THEN (-2) ELSE 0 END) + CASE  WHEN (((sa.ind_curr - sa.ind_prev) > 1)) THEN (1) ELSE 0 END) AS score, concat_ws(', ', CASE  WHEN ((((sa.corp_curr - sa.corp_prev) > 1) AND ((sa.ind_curr - sa.ind_prev) < -0.5))) THEN ('🟢 Corp Acc') ELSE NULL END, CASE  WHEN (((sa.foreign_curr - sa.foreign_prev) > 1)) THEN ('🟢 Foreign In') ELSE NULL END, CASE  WHEN ((((sa.corp_curr + sa.fund_curr) + sa.fin_curr) > 50)) THEN ('💎 Inst Dom') ELSE NULL END, CASE  WHEN ((((sa.corp_curr - sa.corp_prev) < -1) AND ((sa.ind_curr - sa.ind_prev) > 0.5))) THEN ('🔴 Corp Dist') ELSE NULL END, CASE  WHEN (((sa.foreign_curr - sa.foreign_prev) < -1)) THEN ('🔴 Foreign Out') ELSE NULL END, CASE  WHEN (((sa.ind_curr - sa.ind_prev) > 1)) THEN ('🟡 Insider Buy') ELSE NULL END) AS signals FROM stock_aggregate AS sa WHERE ((abs((sa.corp_curr - sa.corp_prev)) >= 0.1) OR (abs((sa.foreign_curr - sa.foreign_prev)) >= 0.1) OR (abs((sa.ind_curr - sa.ind_prev)) >= 0.1)) ORDER BY score DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_ksei_individual_changes
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_ksei_individual_changes AS WITH latest_date AS (SELECT CAST(max(date) AS "DATE") AS max_date FROM ksei.ownership_1pct), individual_changes AS (SELECT o.date, o.share_code, o.investor_name, o.investor_type, o.nationality, o.percentage, o.total_holding_shares, lag(o.percentage) OVER (PARTITION BY o.share_code, o.investor_name ORDER BY o.date) AS prev_percentage, lag(o.total_holding_shares) OVER (PARTITION BY o.share_code, o.investor_name ORDER BY o.date) AS prev_shares FROM ksei.ownership_1pct AS o CROSS JOIN latest_date AS l WHERE ((o.investor_type IN ('ID', 'Individual')) AND (CAST(o.date AS "DATE") >= (l.max_date - CAST('3 months' AS INTERVAL)))))SELECT CAST(date AS "DATE") AS report_date, share_code, investor_name, investor_type, nationality, COALESCE(prev_percentage, percentage) AS prev_percentage, percentage AS curr_percentage, round((percentage - COALESCE(prev_percentage, percentage)), 4) AS pct_point_change, (total_holding_shares - COALESCE(prev_shares, total_holding_shares)) AS share_change, CASE  WHEN ((total_holding_shares > COALESCE(prev_shares, total_holding_shares))) THEN ('BUYING') WHEN ((total_holding_shares < COALESCE(prev_shares, total_holding_shares))) THEN ('SELLING') ELSE 'HOLDING' END AS "action", CASE  WHEN ((abs((percentage - COALESCE(prev_percentage, percentage))) >= 2.0)) THEN ('HIGH') WHEN ((abs((percentage - COALESCE(prev_percentage, percentage))) >= 1.0)) THEN ('MEDIUM') ELSE 'LOW' END AS alert_level FROM individual_changes WHERE ((prev_percentage IS NOT NULL) AND (abs((percentage - COALESCE(prev_percentage, percentage))) >= 0.3)) ORDER BY abs((percentage - COALESCE(prev_percentage, percentage))) DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_ksei_inst_positioning
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_ksei_inst_positioning AS WITH all_snaps AS (SELECT DISTINCT CAST(date AS DATE) AS snap_date FROM ksei.ownership_1pct ORDER BY snap_date DESC), latest_snap AS (SELECT snap_date FROM all_snaps LIMIT 1), prev_snap AS (SELECT snap_date FROM all_snaps LIMIT 1 OFFSET 1), current_own AS (SELECT share_code, sum(percentage) AS total_inst_pct, sum(total_holding_shares) AS total_inst_shares FROM ksei.ownership_1pct WHERE ((CAST(date AS DATE) = (SELECT snap_date FROM latest_snap)) AND (investor_type IN ('ID', 'FD'))) GROUP BY share_code), prev_own AS (SELECT share_code, sum(percentage) AS prev_inst_pct, sum(total_holding_shares) AS prev_inst_shares FROM ksei.ownership_1pct WHERE ((CAST(date AS DATE) = (SELECT snap_date FROM prev_snap)) AND (investor_type IN ('ID', 'FD'))) GROUP BY share_code)SELECT c.share_code AS stock_code, (SELECT snap_date FROM latest_snap) AS latest_snapshot, (SELECT snap_date FROM prev_snap) AS prev_snapshot, c.total_inst_pct, COALESCE(p.prev_inst_pct, c.total_inst_pct) AS prev_inst_pct, round((c.total_inst_pct - COALESCE(p.prev_inst_pct, c.total_inst_pct)), 4) AS mom_change_pct, CASE  WHEN (((c.total_inst_pct - COALESCE(p.prev_inst_pct, c.total_inst_pct)) > 0.5)) THEN ('🟢 Massive Accumulation') WHEN (((c.total_inst_pct - COALESCE(p.prev_inst_pct, c.total_inst_pct)) > 0.1)) THEN ('🟡 Slow Accumulation') WHEN (((c.total_inst_pct - COALESCE(p.prev_inst_pct, c.total_inst_pct)) < -0.5)) THEN ('🔴 Heavy Distribution') WHEN (((c.total_inst_pct - COALESCE(p.prev_inst_pct, c.total_inst_pct)) < -0.1)) THEN ('🟠 Slow Distribution') ELSE '⚪ Stagnant' END AS strategic_signal FROM current_own AS c LEFT JOIN prev_own AS p ON ((c.share_code = p.share_code));

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_ksei_monthly_stock_trend
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_ksei_monthly_stock_trend AS WITH latest_3m AS (SELECT Code, Date, Price, round(((((((Local_CP_Chg_Val + Local_PF_Chg_Val) + Local_IB_Chg_Val) + Foreign_CP_Chg_Val) + Foreign_PF_Chg_Val) + Foreign_IB_Chg_Val) / 1000000000.0), 3) AS net_smart_miliar, round((Local_ID_Chg_Val / 1000000000.0), 3) AS retail_miliar, Top_Buyer, row_number() OVER (PARTITION BY Code ORDER BY Date DESC) AS rn FROM ksei.monthly_snapshot WHERE (Date >= ((SELECT max(Date) FROM ksei.monthly_snapshot) - CAST('90 days' AS INTERVAL)))), agg AS (SELECT Code, max(Date) FILTER (WHERE (rn = 1)) AS latest_month, max(net_smart_miliar) FILTER (WHERE (rn = 1)) AS m0_smart_miliar, max(net_smart_miliar) FILTER (WHERE (rn = 2)) AS m1_smart_miliar, max(net_smart_miliar) FILTER (WHERE (rn = 3)) AS m2_smart_miliar, max(retail_miliar) FILTER (WHERE (rn = 1)) AS m0_retail_miliar, max(Price) FILTER (WHERE (rn = 1)) AS latest_price, max(Top_Buyer) FILTER (WHERE (rn = 1)) AS latest_top_buyer, sum(net_smart_miliar) AS cumulative_3m_smart, count(CASE  WHEN ((net_smart_miliar > 0)) THEN (1) ELSE NULL END) AS months_positive FROM latest_3m GROUP BY Code)SELECT a.Code AS stock_code, cp.sector, cp.group_name, a.latest_month, a.latest_price, a.m0_smart_miliar, a.m1_smart_miliar, a.m2_smart_miliar, a.m0_retail_miliar, a.cumulative_3m_smart, a.months_positive, a.latest_top_buyer, CASE  WHEN (((a.m0_smart_miliar > 0) AND (COALESCE(a.m1_smart_miliar, 0) > 0) AND (COALESCE(a.m2_smart_miliar, 0) > 0))) THEN ('KONSISTEN_AKUMULASI') WHEN (((a.m0_smart_miliar > 0) AND (COALESCE(a.m1_smart_miliar, 0) <= 0))) THEN ('MULAI_AKUMULASI') WHEN (((a.m0_smart_miliar < 0) AND (COALESCE(a.m1_smart_miliar, 0) < 0))) THEN ('KONSISTEN_DISTRIBUSI') WHEN (((a.m0_smart_miliar < 0) AND (COALESCE(a.m1_smart_miliar, 0) >= 0))) THEN ('MULAI_DISTRIBUSI') ELSE 'MIXED' END AS smart_money_trend, CASE  WHEN (((a.m0_smart_miliar > 0) AND (a.m0_retail_miliar < 0))) THEN ('DIVERGEN_BULLISH') WHEN (((a.m0_smart_miliar < 0) AND (a.m0_retail_miliar > 0))) THEN ('DIVERGEN_BEARISH') ELSE 'ALIGNED' END AS divergence_signal FROM agg AS a LEFT JOIN market.company_profile AS cp ON ((a.Code = cp.stock_code));

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_monthly_aggregate
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_monthly_aggregate AS SELECT Date, count(DISTINCT Code) AS Stock_Count, (sum(Local_CP_Chg_Val) / 1000000000000.0) AS Total_CP_Flow_Triliun, (sum(Foreign_CP_Chg_Val) / 1000000000000.0) AS Total_Foreign_CP_Triliun, (sum(Local_ID_Chg_Val) / 1000000000000.0) AS Total_Retail_Triliun, (sum(Top_Buyer_Val) / 1000000000000.0) AS Total_Buy_Triliun, (sum(Top_Seller_Val) / 1000000000000.0) AS Total_Sell_Triliun, count(CASE  WHEN (Is_Split_Suspect) THEN (1) ELSE NULL END) AS Split_Count, count(CASE  WHEN (Is_Reverse_Suspect) THEN (1) ELSE NULL END) AS Reverse_Count FROM ksei.monthly_snapshot GROUP BY Date ORDER BY Date DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_ownership_1pct_latest
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_ownership_1pct_latest AS SELECT o.*, COALESCE(cp.sector, 'Others') AS sector, cp.free_float, COALESCE(cp.group_name, 'Others') AS group_name FROM ksei.ownership_1pct AS o LEFT JOIN market.company_profile AS cp ON ((o.share_code = cp.stock_code)) WHERE (o.date = (SELECT max(date) FROM ksei.ownership_1pct));

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_ownership_latest
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_ownership_latest AS SELECT Code, Date, Price, ((Total_Local / Total_Shares) * 100) AS Local_Pct, ((Total_Foreign / Total_Shares) * 100) AS Foreign_Pct, ((Local_CP / Total_Shares) * 100) AS Local_CP_Pct, ((Foreign_CP / Total_Shares) * 100) AS Foreign_CP_Pct, ((Local_ID / Total_Shares) * 100) AS Local_ID_Pct, Total_Local, Total_Foreign, Total_Shares FROM ksei.monthly_snapshot WHERE (Date = (SELECT max(Date) FROM ksei.monthly_snapshot));

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_s_ksei_concentration
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_s_ksei_concentration AS WITH ranked AS (SELECT share_code, date, investor_name, investor_type, local_foreign, nationality, percentage, total_holding_shares, row_number() OVER (PARTITION BY share_code, date ORDER BY percentage DESC) AS holder_rank FROM ksei.ownership_1pct), aggregated AS (SELECT share_code, date, count(DISTINCT investor_name) AS total_holders, sum(percentage) AS total_pct_held, sum(percentage) FILTER (WHERE (holder_rank <= 5)) AS top5_pct, sum(percentage) FILTER (WHERE (holder_rank <= 10)) AS top10_pct, sum(percentage) FILTER (WHERE (local_foreign IN ('F', 'A'))) AS foreign_holder_pct, sum(percentage) FILTER (WHERE (local_foreign IN ('L', 'D', 'I'))) AS local_holder_pct, sum(power((percentage / 100.0), 2)) AS hhi_score, count(DISTINCT investor_name) AS holder_count FROM ranked GROUP BY share_code, date)SELECT a.*, CASE  WHEN ((a.top5_pct >= 80)) THEN ('VERY_HIGH') WHEN ((a.top5_pct >= 60)) THEN ('HIGH') WHEN ((a.top5_pct >= 40)) THEN ('MODERATE') ELSE 'LOW' END AS concentration_tier, (a.foreign_holder_pct > a.local_holder_pct) AS foreign_dominated, COALESCE(cp.sector, 'Others') AS sector, COALESCE(cp.group_name, 'Others') AS group_name, cp.free_float FROM aggregated AS a LEFT JOIN market.company_profile AS cp ON ((a.share_code = cp.stock_code));

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_s_ksei_foreign_breakdown
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_s_ksei_foreign_breakdown AS SELECT ib.stock_code, ib.snapshot_date, ib.price_idr, ib.foreign_cp_chg_miliar, ib.foreign_pf_chg_miliar, ib.foreign_ib_chg_miliar, ib.foreign_is_chg_miliar, ib.foreign_mf_chg_miliar, ib.foreign_id_chg_miliar, round(((((ib.foreign_cp_chg_miliar + ib.foreign_pf_chg_miliar) + ib.foreign_ib_chg_miliar) + ib.foreign_is_chg_miliar) + ib.foreign_mf_chg_miliar), 3) AS institutional_foreign_miliar, CASE  WHEN (((ib.foreign_pf_chg_miliar = greatest(ib.foreign_cp_chg_miliar, ib.foreign_pf_chg_miliar, ib.foreign_ib_chg_miliar, ib.foreign_is_chg_miliar, ib.foreign_mf_chg_miliar)) AND (ib.foreign_pf_chg_miliar > 0))) THEN ('PENSION_FUND') WHEN (((ib.foreign_cp_chg_miliar = greatest(ib.foreign_cp_chg_miliar, ib.foreign_pf_chg_miliar, ib.foreign_ib_chg_miliar, ib.foreign_is_chg_miliar, ib.foreign_mf_chg_miliar)) AND (ib.foreign_cp_chg_miliar > 0))) THEN ('CORPORATE') WHEN (((ib.foreign_ib_chg_miliar = greatest(ib.foreign_cp_chg_miliar, ib.foreign_pf_chg_miliar, ib.foreign_ib_chg_miliar, ib.foreign_is_chg_miliar, ib.foreign_mf_chg_miliar)) AND (ib.foreign_ib_chg_miliar > 0))) THEN ('BANK') WHEN ((ib.foreign_is_chg_miliar > 0)) THEN ('INSURANCE') WHEN ((ib.foreign_mf_chg_miliar > 0)) THEN ('MUTUAL_FUND') ELSE 'NONE_BUYING' END AS dominant_foreign_buyer, ((ib.foreign_cp_chg_miliar > 0) OR (ib.foreign_pf_chg_miliar > 0) OR (ib.foreign_ib_chg_miliar > 0) OR (ib.foreign_is_chg_miliar > 0)) AS inst_foreign_entry, (ib.foreign_pf_chg_miliar > 0) AS pension_fund_buying, ib.foreign_cp_pct, ib.foreign_pf_pct, ib.foreign_is_pct, ib.sector, ib.group_name FROM ksei.vw_f_ksei_investor_breakdown AS ib;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_s_ksei_retail_distribution
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_s_ksei_retail_distribution AS SELECT stock_code, snapshot_date, smart_money_miliar, retail_miliar, smart_retail_divergence, CASE  WHEN (((smart_money_miliar < 0) AND (retail_miliar > 0))) THEN ('CONFIRMED') WHEN (((smart_money_miliar < 0) AND (retail_miliar = 0))) THEN ('WARNING') WHEN (((smart_money_miliar > 0) AND (retail_miliar < 0))) THEN ('BULLISH_DIVERGENCE') WHEN (((smart_money_miliar > 0) AND (retail_miliar > 0))) THEN ('ALL_IN') ELSE 'NEUTRAL' END AS distribution_signal, CASE  WHEN (((smart_money_miliar < 0) AND (retail_miliar > 0))) THEN (round((retail_miliar / "nullif"(abs(smart_money_miliar), 0)), 2)) ELSE NULL END AS retail_absorption_ratio, Is_Split_Suspect, Is_Reverse_Suspect, sector, group_name FROM ksei.vw_f_ksei_rolling_trend;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_s_ksei_smart_entry
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_s_ksei_smart_entry AS SELECT rt.stock_code, rt.snapshot_date, rt.price_idr, rt.smart_money_miliar, rt.local_smart_miliar, rt.foreign_smart_miliar, rt.retail_miliar, rt.sm_trend, rt.sm_positive, rt.sm_2m_positive, rt.sm_3m_positive, rt.sm_mom_delta, rt.sm_3m_cumulative_miliar, rt.smart_retail_divergence, rt.Is_Split_Suspect, rt.Is_Reverse_Suspect, CASE  WHEN (rt.sm_3m_positive) THEN ('CONSISTENT_3M') WHEN (rt.sm_2m_positive) THEN ('CONSISTENT_2M') WHEN ((rt.sm_positive AND (NOT rt.sm_2m_positive) AND (rt.sm_mom_delta > 0))) THEN ('NEW_ENTRY_ACCELERATING') WHEN ((rt.sm_positive AND (NOT rt.sm_2m_positive))) THEN ('NEW_ENTRY') WHEN (((NOT rt.sm_positive) AND (rt.sm_mom_delta > 0))) THEN ('IMPROVING') ELSE 'DISTRIBUTING' END AS sm_entry_type, CASE  WHEN ((rt.Is_Split_Suspect OR rt.Is_Reverse_Suspect)) THEN ('UNRELIABLE') WHEN ((rt.sm_3m_positive AND (rt.smart_retail_divergence = 'DIVERGENT_BULLISH'))) THEN ('PREMIUM') WHEN (rt.sm_3m_positive) THEN ('HIGH') WHEN (rt.sm_2m_positive) THEN ('MEDIUM') WHEN (rt.sm_positive) THEN ('LOW') ELSE 'NONE' END AS signal_quality, rt.sector, rt.group_name FROM ksei.vw_f_ksei_rolling_trend AS rt;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_smart_money
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_smart_money AS SELECT Code, Date, Price, (((Local_CP_Chg_Val + Local_IB_Chg_Val) + Local_PF_Chg_Val) / 1000000000.0) AS Local_Smart_Miliar, (((Foreign_CP_Chg_Val + Foreign_IB_Chg_Val) + Foreign_PF_Chg_Val) / 1000000000.0) AS Foreign_Smart_Miliar, ((((((Local_CP_Chg_Val + Local_IB_Chg_Val) + Local_PF_Chg_Val) + Foreign_CP_Chg_Val) + Foreign_IB_Chg_Val) + Foreign_PF_Chg_Val) / 1000000000.0) AS Net_Smart_Miliar, ((Local_ID_Chg_Val + Foreign_ID_Chg_Val) / 1000000000.0) AS Retail_Miliar, Total_Shares, Is_Split_Suspect, Is_Reverse_Suspect FROM ksei.monthly_snapshot;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_stealth_accumulation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_stealth_accumulation AS WITH price_changes AS (SELECT Code, Date, Price, (Local_CP_Chg_Val / 1000000000.0) AS CP_Flow_Miliar, (Foreign_CP_Chg_Val / 1000000000.0) AS Foreign_CP_Miliar, lag(Price) OVER (PARTITION BY Code ORDER BY Date) AS Prev_Price FROM ksei.monthly_snapshot WHERE (Date >= ((SELECT max(Date) FROM ksei.monthly_snapshot) - CAST('12 months' AS INTERVAL))))SELECT Code, Date, Price, Prev_Price, round((((Price - Prev_Price) / "nullif"(Prev_Price, 0)) * 100), 2) AS Price_Chg_Pct, CP_Flow_Miliar, Foreign_CP_Miliar, CASE  WHEN (((CP_Flow_Miliar > 10) AND (((Price - Prev_Price) / "nullif"(Prev_Price, 0)) BETWEEN -0.03 AND 0.03))) THEN ('🕵️ STEALTH ACCUMULATION') WHEN (((CP_Flow_Miliar > 50) AND (((Price - Prev_Price) / "nullif"(Prev_Price, 0)) < -0.03))) THEN ('💰 BUYING THE DIP') WHEN (((CP_Flow_Miliar < -10) AND (((Price - Prev_Price) / "nullif"(Prev_Price, 0)) > 0.03))) THEN ('📤 DISTRIBUTION') ELSE 'NORMAL' END AS Signal FROM price_changes WHERE ((Prev_Price IS NOT NULL) AND (CP_Flow_Miliar IS NOT NULL)) ORDER BY abs(CP_Flow_Miliar) DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_top_investors
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_top_investors AS SELECT investor_name, investor_type, local_foreign, nationality, count(DISTINCT share_code) AS total_saham, sum(total_holding_shares) AS total_shares, round(avg(percentage), 2) AS avg_percentage FROM ksei.ownership_1pct WHERE (date = (SELECT max(date) FROM ksei.ownership_1pct)) GROUP BY investor_name, investor_type, local_foreign, nationality ORDER BY total_saham DESC;

-- ─────────────────────────────────────────────────────────────
-- ksei.vw_whale_timing
-- ─────────────────────────────────────────────────────────────
CREATE VIEW ksei.vw_whale_timing AS WITH whale_dates AS (SELECT share_code, investor_name, investor_type, local_foreign, min(CAST(date AS DATE)) AS first_seen_date, max(CAST(date AS DATE)) AS latest_date FROM ksei.ownership_1pct GROUP BY share_code, investor_name, investor_type, local_foreign), first_record AS (SELECT DISTINCT ON (share_code, investor_name) share_code, investor_name, percentage AS first_percentage FROM ksei.ownership_1pct ORDER BY share_code, investor_name, CAST(date AS DATE) ASC), latest_record AS (SELECT DISTINCT ON (share_code, investor_name) share_code, investor_name, percentage AS latest_percentage, total_holding_shares AS latest_shares FROM ksei.ownership_1pct ORDER BY share_code, investor_name, CAST(date AS DATE) DESC), entry_price AS (SELECT wh.share_code, wh.investor_name, round(avg(dt."close"), 2) AS est_entry_price FROM whale_dates AS wh INNER JOIN market.daily_transactions AS dt ON (((dt.stock_code = wh.share_code) AND (dt.trading_date BETWEEN wh.first_seen_date AND (wh.first_seen_date + CAST('30 days' AS INTERVAL))))) GROUP BY wh.share_code, wh.investor_name)SELECT wh.share_code, wh.investor_name, wh.investor_type, wh.local_foreign, wh.first_seen_date, wh.latest_date, fr.first_percentage, lr.latest_percentage, lr.latest_shares, COALESCE(ep.est_entry_price, 0) AS est_entry_price, lat.current_price, CASE  WHEN (((COALESCE(ep.est_entry_price, 0) > 0) AND (lat.current_price > 0))) THEN (round((((lat.current_price - ep.est_entry_price) / ep.est_entry_price) * 100), 2)) ELSE NULL END AS return_since_entry, CAST((wh.latest_date - wh.first_seen_date) AS INTEGER) AS holding_days, CASE  WHEN ((lr.latest_percentage > (fr.first_percentage + 1))) THEN ('INCREASING') WHEN ((lr.latest_percentage < (fr.first_percentage - 1))) THEN ('DECREASING') ELSE 'STABLE' END AS position_trend, CASE  WHEN (((lr.latest_percentage > (fr.first_percentage + 1)) AND (lat.current_price < COALESCE(ep.est_entry_price, 0)))) THEN ('AVERAGING_DOWN') WHEN ((lr.latest_percentage > (fr.first_percentage + 1))) THEN ('ADDING_POSITION') WHEN ((lr.latest_percentage < (fr.first_percentage - 1))) THEN ('TRIMMING') ELSE 'LONG_TERM_HOLD' END AS whale_verdict FROM whale_dates AS wh INNER JOIN first_record AS fr ON (((fr.share_code = wh.share_code) AND (fr.investor_name = wh.investor_name))) INNER JOIN latest_record AS lr ON (((lr.share_code = wh.share_code) AND (lr.investor_name = wh.investor_name))) LEFT JOIN entry_price AS ep ON (((ep.share_code = wh.share_code) AND (ep.investor_name = wh.investor_name))) LEFT JOIN (SELECT "close" AS current_price FROM market.daily_transactions WHERE (stock_code = wh.share_code) ORDER BY trading_date DESC LIMIT 1) AS lat ON (CAST('t' AS BOOLEAN)) ORDER BY lr.latest_percentage DESC;
